{"edits":[{"path":"directory.py","content":"from utils import normalize_email


class UserDirectory:
    def __init__(self):
        self.users = {}

    def storage_key(self, email: str) -> str:
        # FIXED: use normalized email as the storage key
        return normalize_email(email)

    def add_user(self, email: str, name: str):
        key = self.storage_key(email)
        self.users[key] = name

    def get_user(self, email: str):
        key = normalize_email(email)
        return self.users.get(key)
